// What we ask of the customer before a visit, grouped by category type
// (care / home / wellness / vehicle — the same groups as categoryGroups).
// This is our own general guidance, not a per-service business rule, so it
// is generated by group rather than hand-written 30 times.

const REQUIREMENTS_BY_GROUP = {
  care: [
    "Share any special instructions or care needs while booking",
    "Make sure someone is available to welcome the professional",
    "Let us know about allergies, medical needs, or routines in advance",
  ],
  home: [
    "Make sure someone above 18 is present during the visit",
    "Clear the work area of fragile or valuable items",
    "Share access details (parking, gate code, floor) while booking",
  ],
  wellness: [
    "Provide a clean, well-lit space for the service",
    "Share any allergies or skin/scalp sensitivities in advance",
    "Make sure water and a power point are accessible if needed",
  ],
  vehicle: [
    "Park the vehicle in an accessible, well-lit spot",
    "Remove personal belongings before the visit",
    "Share the vehicle type and any specific concerns while booking",
  ],
};

export function getRequirements(group) {
  return REQUIREMENTS_BY_GROUP[group] ?? [];
}
